style.css:
@-moz-document domain("utp.edu.pe") {
/* Fondo de la página en rosado pastel */
    body, .container, .page-wrapper, .main-content, .content-wrapper, .content {
        background-color: #f8e1e8 !important;
    }

    /* Color de texto en negro */
    body, p, a, h1, h2, h3, h4, h5, h6, .card, .list-group-item {
        color: #000000 !important;
    }

    /* Fondo de las tarjetas o secciones de la página en rosado claro */
    .card, .list-group-item, .row, .col {
        background-color: #f7a8c8 !important;
    }

    /* Botones con color rosado pastel */
    button, .btn, .submit-button {
        background-color: #f7a8c8 !important;
        color: white !important;
    }

    /* Enlaces con color rosado pastel y un tono más fuerte al pasar el ratón */
    a {
        color: #f5b4cc !important;
    }

    a:hover {
        color: #f07ca5 !important;
    }

    /* Encabezados con un rosado suave */
    h1, h2, h3, h4, h5, h6 {
        color: #e36c88 !important;
    }

    /* Bordes de los formularios en color rosado pastel */
    input, textarea, select {
        border-color: #f7a8c8 !important;
    }

    /* Cambiar el color de los enlaces activos */
    a:active {
        color: #f07ca5 !important;
    }

    /* Cambiar todos los elementos que usan el color celeste (como el borde superior) a rosado celeste */
    .navbar, .header, .footer, .topbar, .sidebar {
        background-color: #f7b8d3 !important;
    }

    /* Colores de las pestañas o enlaces de navegación */
    .nav-link, .navbar-brand {
        color: #f7b8d3 !important;
    }

    /* Elementos con fondo celeste que se deben cambiar a rosado claro */
    .btn-link, .search-bar {
        background-color: #f7b8d3 !important;
    }
}
